-- VJ Car Rental Version 3
-- Vehicle database only for Version 3.


CREATE DATABASE IF NOT EXISTS `vj_car_rental_v3` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE `vj_car_rental_v3`;

DROP TABLE IF EXISTS `vehicles`;

CREATE TABLE `vehicles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(140) NOT NULL,
  `name` varchar(180) NOT NULL,
  `brand` varchar(100) NOT NULL,
  `category` varchar(40) NOT NULL,
  `image` varchar(255) NOT NULL,
  `price` int(11) NOT NULL,
  `seats` int(11) NOT NULL,
  `doors` int(11) NOT NULL,
  `luggage` varchar(80) NOT NULL,
  `transmission` varchar(40) NOT NULL,
  `fuel` varchar(40) NOT NULL,
  `daily_km` int(11) NOT NULL DEFAULT 200,
  `overview_title` varchar(255) NOT NULL,
  `overview` longtext NOT NULL,
  `description` longtext NOT NULL,
  `inclusions` longtext NOT NULL,
  `features` longtext NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_vehicles_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


ALTER TABLE `vehicles` AUTO_INCREMENT=76;
